if size=='390':
 call('native-text-card-ready-390', 'const p=getCurrentPages().slice(-1)[0];p.openTextCard("editor");await wait(()=>p.data.textCardVisible&&p.selectComponent("#communityTextCard").data.visible);const c=p.selectComponent("#communityTextCard");c.editText({detail:{value:"今天认真完成了护理。"+String.fromCharCode(10)+"把每一次真实感受记下来 💜"}});c.selectTemplate({currentTarget:{dataset:{template:"lilac"}}});await wait(()=>c.data.canExport);return {previewReady:!!c.data.previewPath,canExport:c.data.canExport,error:c.data.error};')
 shot('native-text-card-390')
 png=call('native-text-card-confirm-390', 'const p=getCurrentPages().slice(-1)[0];await p.selectComponent("#communityTextCard").confirm();await wait(()=>!p.data.textCardVisible&&!p.data.uploadBusy&&p.data.files.length===1);const file=p.data.files[0];return {stageClosed:!p.data.textCardVisible,files:p.data.files.length,error:p.data.error,signature:await new Promise((resolve,reject)=>wx.getFileSystemManager().readFile({filePath:file.localPath,position:0,length:8,success:r=>resolve(Array.from(new Uint8Array(r.data))),fail:reject}))};')
 assert png['signature']==[137,80,78,71,13,10,26,10]
