assert dirty['cancelledOnlyTool'] and dirty['dirty'] and dirty['geometry'][:3]==[None,None,None] and dirty['geometry'][3]['disabled'] is False
shot('native-photo-tool-'+size)
done=call('native-tool-done-'+size, 'const p=getCurrentPages().slice(-1)[0],e=p.selectComponent("#communityImageEditor"),before=e.data.files[0].path;await e.confirm();await wait(()=>!e.data.busy&&!e.data.activeTool&&!e.data.effectDirty);const file=e.data.files[0];return {scope:"Done actually renders JPEG and returns to image overview only",editorStillOpen:p.data.photoEditorVisible,activeTool:e.data.activeTool,dirty:e.data.effectDirty,newPath:file.path!==before,error:e.data.error,uploadAuthorizeCount:getApp().globalData.motionFixture.calls.filter(x=>x.path.endsWith("/authorize")).length,parentFiles:p.data.files.length,signature:await new Promise((resolve,reject)=>wx.getFileSystemManager().readFile({filePath:file.path,position:0,length:3,success:r=>resolve(Array.from(new Uint8Array(r.data))),fail:reject}))};')
assert done['editorStillOpen'] and done['newPath'] and done['signature']==[255,216,255] and done['uploadAuthorizeCount']==dirty['uploadAuthorizeCount'] and done['parentFiles']==dirty['parentFiles']
shot('native-photo-overview-'+size)
