if size=='390':
 submitted=call('native-direct-submit-390', 'const p=getCurrentPages().slice(-1)[0];await p.submit();const f=getApp().globalData.motionFixture;return {scope:"fixture submit creates a review revision; not real backend105 acceptance",state:p.data.state,publicVersionActive:p.data.publicVersionActive,version:p.data.version,revision:f.posts[p.data.postId].revision,writePayloads:f.calls.filter(x=>x.method!=="GET").map(x=>({method:x.method,path:x.path,keys:x.dataKeys})),error:p.data.error,notice:p.data.notice};')
